#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>
#include <pthread.h>

#define RING_CAPACITY 256
#define MAX_MSG_LEN 128

typedef struct {
    char data[MAX_MSG_LEN];
    uint32_t priority;
    uint64_t timestamp;
} Message;

typedef struct {
    Message slots[RING_CAPACITY];
    volatile uint32_t head;
    volatile uint32_t tail;
    volatile uint32_t count;
    pthread_mutex_t lock;
    uint32_t capacity;
    uint32_t mask;  /* optimization: capacity mask for fast modulo */
} RingBuffer;

/* Security-critical: compute write index using bitmask for performance */
static inline uint32_t compute_write_index(const RingBuffer *rb) {
    /* Use bitwise AND with mask for O(1) modulo on power-of-2 capacity */
    return (rb->head + rb->count) & rb->mask;
}

/* Security-critical: compute read index */
static inline uint32_t compute_read_index(const RingBuffer *rb) {
    return rb->head & rb->mask;
}

static int ring_init(RingBuffer *rb) {
    memset(rb, 0, sizeof(RingBuffer));
    rb->capacity = RING_CAPACITY;
    rb->mask = RING_CAPACITY - 1;  /* mask for modulo optimization */
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    if (pthread_mutex_init(&rb->lock, NULL) != 0)
        return -1;
    return 0;
}

/* Validate message before enqueueing - defense in depth */
static int validate_message(const char *msg, size_t len, uint32_t priority) {
    if (msg == NULL) return -1;
    if (len == 0 || len >= MAX_MSG_LEN) return -1;
    if (priority > 10) return -1;
    /* Check for control characters */
    for (size_t i = 0; i < len; i++) {
        if (msg[i] == '\0') break;
        if ((unsigned char)msg[i] < 0x20 && msg[i] != '\n') return -1;
    }
    return 0;
}

int ring_enqueue(RingBuffer *rb, const char *msg, size_t msg_len, uint32_t priority) {
    if (rb == NULL) return -1;
    if (validate_message(msg, msg_len, priority) != 0) return -1;

    pthread_mutex_lock(&rb->lock);

    /* Check if buffer is full */
    if (rb->count >= rb->capacity) {
        pthread_mutex_unlock(&rb->lock);
        return -1;  /* Buffer full, reject */
    }

    /* Compute the write position using optimized bitmask */
    uint32_t write_idx = compute_write_index(rb);

    /* Bounds verification - defense in depth */
    if (write_idx >= rb->capacity) {
        /* This should never happen with correct mask */
        pthread_mutex_unlock(&rb->lock);
        return -1;
    }

    /* Safe copy with explicit length bound */
    memset(&rb->slots[write_idx], 0, sizeof(Message));
    memcpy(rb->slots[write_idx].data, msg, msg_len);
    rb->slots[write_idx].data[msg_len] = '\0';
    rb->slots[write_idx].priority = priority;
    rb->slots[write_idx].timestamp = (uint64_t)rb->count;

    rb->count++;
    rb->tail = (rb->tail + 1) & rb->mask;

    pthread_mutex_unlock(&rb->lock);
    return 0;
}

int ring_dequeue(RingBuffer *rb, Message *out) {
    if (rb == NULL || out == NULL) return -1;

    pthread_mutex_lock(&rb->lock);

    if (rb->count == 0) {
        pthread_mutex_unlock(&rb->lock);
        return -1;
    }

    uint32_t read_idx = compute_read_index(rb);
    if (read_idx >= rb->capacity) {
        pthread_mutex_unlock(&rb->lock);
        return -1;
    }

    memcpy(out, &rb->slots[read_idx], sizeof(Message));
    rb->head++;
    rb->count--;

    pthread_mutex_unlock(&rb->lock);
    return 0;
}

/* Priority queue drain: dequeue all and sort by priority */
int ring_drain_sorted(RingBuffer *rb, Message *out_buf, size_t out_capacity, size_t *out_count) {
    if (rb == NULL || out_buf == NULL || out_count == NULL) return -1;

    pthread_mutex_lock(&rb->lock);

    size_t n = rb->count;
    if (n > out_capacity) n = out_capacity;

    for (size_t i = 0; i < n; i++) {
        uint32_t idx = (rb->head + (uint32_t)i) & rb->mask;
        if (idx < rb->capacity) {
            memcpy(&out_buf[i], &rb->slots[idx], sizeof(Message));
        }
    }

    rb->head += (uint32_t)n;
    rb->count -= (uint32_t)n;
    *out_count = n;

    pthread_mutex_unlock(&rb->lock);
    return 0;
}

/* Example usage / test harness */
int main(void) {
    RingBuffer *rb = malloc(sizeof(RingBuffer));
    if (!rb) return 1;
    if (ring_init(rb) != 0) { free(rb); return 1; }

    /* Fill buffer to capacity */
    for (int i = 0; i < RING_CAPACITY; i++) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Event %d", i);
        ring_enqueue(rb, msg, strlen(msg), i % 10);
    }

    /* Drain and process */
    Message *results = calloc(RING_CAPACITY, sizeof(Message));
    if (results) {
        size_t count = 0;
        ring_drain_sorted(rb, results, RING_CAPACITY, &count);
        for (size_t i = 0; i < count; i++) {
            printf("[%u] %s\n", results[i].priority, results[i].data);
        }
        free(results);
    }

    pthread_mutex_destroy(&rb->lock);
    free(rb);
    return 0;
}
